{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the delay compensation, is the delay measured as the number of quarters a unit is late relative to its contract quarter (so a unit of product I produced in Q3 to cover Q1 demand costs 20×2 = 40 yuan), or is it a flat 20 yuan per late unit regardless of how many quarters late it is?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive calculation methods for delay compensation."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can production in a later quarter be used to satisfy demand from an earlier quarter (i.e., is backlogging/late delivery allowed), or must each quarter's contract demand be fully met by production in that same quarter or earlier?"
  ],
  "rationale": "The response asks a single clarification question regarding the policy on backlogging or late delivery, presenting two mutually exclusive options for the same decision."
}

